import { Field, Formik, Form } from "formik";
import { useReducer } from "react";
import reducer, { initialState } from "./reducer";
import { DEVELOPER, NUMBER } from "./actionTypes";

import "./App.css";

function App() {
  const [state, dispatch] = useReducer(reducer, initialState);

  function developer() {
    dispatch({ type: DEVELOPER });
  }

  function number() {
    dispatch({ type: NUMBER, payload: 4})
  }

  return (
    <div className="appContainer">
      <div className="mainApp">
        <div className="buttons">
          <Formik initialValues={{ username: "" }}>
            <Form>
              <p>Enter Username</p>
              <Field name="username" />
              <button type="button" onClick={developer}>
                ADD DEVELOPER
              </button>
              <button type="button" >SHUFFLE ARRAY</button>
              <button type="button"  onClick={number}>
                ADD NUMBER
              </button>
              <button type="button" >REMOVE SINGLE DIGITS</button>
              <button type="button" >CHANGE USER</button>
              <button type="button" >ADD AGE</button>
            </Form>
          </Formik>
        </div>
        <div className="output">
          <p>Output</p>
          <p></p>
        </div>
      </div>
    </div>
  );
}

export default App;
